import h5py,pandas as pd,json
m=pd.read_csv('site_meta.csv',low_memory=False)
with h5py.File('lung.cancer.sc.h5ad','r') as f:
 idx=f['obs/_index'][:].astype(str); codes=f['obs/sampleID/codes'][:]; cats=f['obs/sampleID/categories'][:].astype(str)
sets={s:set(g.Cells.astype(str).str.rsplit('_',n=1).str[-1]) for s,g in m.groupby('SampleID',sort=False)}
mapx={}
h5=set()
for i,p in enumerate(cats):
 vals=idx[codes==i]; bare={v.split('_',2)[2] for v in vals}
 cand=[s for s,ss in sets.items() if len(bare&ss)==len(bare) and len(ss)==len(bare)]
 mapx[p]=cand[0]; h5|={cand[0]+'_'+v.split('_',2)[2] for v in vals}
x=json.load(open('coord_cell_Basal_disease_LUSC_coord_umap_group_cluster.json'))
mal=[z[3] for v in x['data'].values() for z in v]
print('missing',set(mal)-h5)
for cid in set(mal)-h5:
 print(m[m.Cells.astype(str)==cid].to_string(index=False))
# counts by h5 sample
from collections import Counter
c=Counter()
for v in x['data'].values():
 for z in v:c[z[4]]+=1
print('all')
for p,s in mapx.items():
 if s in c: print(p,s,c[s])
PY"
